<template><PageShell title="Administrative Accounts" subtitle="Manage Technical Super Admin and Platform Executive accounts without entering operational approval workflows." icon="lucide:shield-user" eyebrow="Technical Super Admin"><section class="overflow-hidden rounded-3xl border border-base-300 bg-base-100 shadow-sm dark:border-white/10 dark:bg-[#071829]"><div class="grid gap-3 border-b border-base-300 p-4 md:grid-cols-[1fr_auto]"><input v-model="search" class="rounded-xl border border-base-300 bg-base-100 px-4 py-2.5 text-sm dark:bg-white/5 dark:text-white" placeholder="Search administrators..." @keyup.enter="load"/><button class="rounded-xl border border-base-300 px-4 text-xs font-black" @click="load">Refresh</button></div><div class="divide-y divide-base-300 dark:divide-white/5"><article v-for="a in items" :key="a.id" class="flex flex-wrap items-center justify-between gap-4 p-5"><div><p class="font-black text-slate-800 dark:text-white/75">{{ a.name }}</p><p class="mt-1 text-xs text-slate-400">{{ a.email }} · {{ pretty(a.role) }}</p><p class="mt-1 text-[.68rem] text-slate-400">2FA: {{ a.has_two_factor?'Enabled':'Not enabled' }} · Last login: {{ format(a.last_login_at) }}</p></div><div class="flex items-center gap-2"><span class="rounded-full px-2.5 py-1 text-[.65rem] font-black" :class="a.account_status==='active'?'bg-emerald-100 text-emerald-700':'bg-amber-100 text-amber-700'">{{ a.account_status }}</span><button v-if="a.account_status==='active'" class="rounded-xl border border-amber-300 px-3 py-2 text-xs font-black text-amber-700" @click="change(a,'suspended')">Suspend</button><button v-else class="rounded-xl bg-emerald-600 px-3 py-2 text-xs font-black text-white" @click="change(a,'active')">Reactivate</button></div></article><p v-if="!items.length" class="py-16 text-center text-sm text-slate-400">No administrative accounts found.</p></div></section></PageShell></template>
<script setup>import{onMounted,ref}from'vue';import PageShell from '@/components/management/PageShell.vue';import{fetchTechnicalAccounts,updateTechnicalAccountStatus}from'@/services/adminCompletion';import{useAlert}from'@/composables/useAlert';import{useToast}from'@/composables/useToast';const alert=useAlert(),toast=useToast(),items=ref([]),search=ref('');const pretty=v=>String(v||'').replaceAll('_',' ').replace(/\b\w/g,m=>m.toUpperCase());const format=v=>v?new Date(String(v).replace(' ','T')).toLocaleString():'Never';async function load(){const d=await fetchTechnicalAccounts({search:search.value});items.value=d.items||[]}async function change(a,status){let reason='';if(status!=='active'){const ok=await alert.confirm(`Suspend ${a.name}? Their current session will stop working on the next session refresh.`, 'Suspend administrative account');if(!ok)return;reason='Administrative suspension by Technical Super Admin.'}try{const d=await updateTechnicalAccountStatus({user_id:a.id,status,reason});toast.success(d.message);await load()}catch(e){toast.error(e?.response?.data?.message||'Unable to update account.')}}onMounted(load)</script>
